join catalog_composition c on c.organization_id = (select id from organization where code = 'EIFF') and c.source = 'SINAPI' and c.code = v.comp
left join catalog_input i on v.tipo = 'I' and i.organization_id = (select id from organization where code = 'EIFF') and i.source = 'SINAPI' and i.code = v.ref
left join catalog_composition cc on v.tipo = 'C' and cc.organization_id = (select id from organization where code = 'EIFF') and cc.source = 'SINAPI' and cc.code = v.ref
where i.id is not null or cc.id is not null;
